function itemsFromHTML(html) { return parseHTML(html, "article, .card, .movie, .film, .item, .post, a[href*='stream']").map((node, index) => { const title = String(node.text || "").replace(/\s+/g, " ").trim().slice(0, 180); const url = node.href || ""; return { id: url || String(index), title, type: "Live", url, poster: node.dataSrc || node.src || null }; }).filter(item => item.title && item.url); }
async function getMainPage(page, sectionKey) { return { items: itemsFromHTML(await providerText(sectionKey || BASE_URL)), hasNextPage: false }; }
